    public class Solution {
      public static final BigInteger TWO = BigInteger.valueOf(2);

      public static List<BigInteger> fibonacciSeries(final int n){
          List<BigInteger> resultList = new ArrayList<>();

          BigInteger previousNumber = BigInteger.ONE;
          BigInteger currentNumber = BigInteger.ONE;

          for (int i = 0; i < n; i++){
              resultList.add(currentNumber);

              BigInteger tempPreviousNumber = previousNumber;
              previousNumber = currentNumber;
              currentNumber = tempPreviousNumber.add(previousNumber);
          }

          return resultList;
      }

