          Scanner scan = new Scanner(System.in);
          int n = scan.nextInt();

          List<BigInteger> listOfNumbers = fibonacciSeries(n);

          for (BigInteger numberToBeDisplayed : listOfNumbers){
              System.out.print(numberToBeDisplayed+" ");
          }
      }
    }
