    static String revStrRecursive(String str){     
        //Your code here

        if(str.length()==1 || str.isEmpty())return str;
        return revStrRecursive(str.substring(1))+str.charAt(0);
    }
    //Function to reverse a string without using extra space.
    static String revStrIterative(String str){      
        //Your code here
        if(str.length()<2)return str;
        Stack<Character> stack=new Stack<>();
        for(char ch:str.toCharArray()){
            stack.push(ch);
        }
        StringBuilder ans=new StringBuilder();
        while(!stack.empty()){
            ans.append(stack.pop());
        }
        return ans.toString();
    }
    //Driver Program
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        String str=sc.next();
        System.out.println(revStrRecursive(str));
        System.out.println(revStrIterative(str));
    }
}
